theme.css:
/* theme: Crude Crosscurrents | A newsprint palette of oil-slick navy and Brent red, with a typographic system that mirrors the day's mix of calm diplomacy hopes and jittery market swings. */

.diary-page {
  --paper: #f5f2ea;
  --paper-alt: #ece7db;
  --ink: #1a1f24;
  --ink-soft: #3a4047;
  --muted: #5c6268;
  --accent: #a63c2c;
  --accent-ink: #f8f4ec;
  --rule: #cfc8ba;
  --font-display: var(--ff-fraunces), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #14161a;
    --paper-alt: #1d2025;
    --ink: #e8e4d9;
    --ink-soft: #c7c2b4;
    --muted: #96958b;
    --accent: #d9725e;
    --accent-ink: #1a0d08;
    --rule: #2e2b26;
  }
}

.diary-page .diary-hero {
  background: linear-gradient(180deg, var(--paper-alt) 0%, var(--paper) 100%);
  border-bottom: 2px solid var(--accent);
}

.diary-page .diary-hero-inner {
  padding-block: 2rem 3.5rem;
}

.diary-page .diary-kicker {
  font-size: 0.75rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.75rem, 7vw, 5.5rem);
  font-weight: 650;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--ink);
  text-wrap: balance;
}

.diary-page .diary-summary {
  font-size: clamp(1.15rem, 2vw, 1.35rem);
  line-height: 1.65;
  color: var(--ink-soft);
  max-width: 50rem;
}

.diary-page .diary-theme-note {
  font-size: 0.85rem;
  color: var(--muted);
  max-width: 44rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  letter-spacing: 0.02em;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    background: none;
    border-bottom: 0;
  }

  .diary-page .diary-toc-label {
    font-size: 0.7rem;
    letter-spacing: 0.2em;
    color: var(--muted);
  }

  .diary-page .diary-toc-list {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link {
    padding-left: 1.1rem;
    font-size: 0.9rem;
    font-weight: 500;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
    font-weight: 600;
  }
}

.diary-page .diary-toc-top {
  font-weight: 500;
  color: var(--muted);
}

.diary-page .diary-toc-number {
  font-weight: 600;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section:first-child {
  border-top: 0;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.9rem, 3.6vw, 2.75rem);
  font-weight: 620;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--ink);
}

.diary-page .diary-prose {
  font-size: 1.15rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-prose strong {
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-prose ul > li {
  padding-left: 1.4rem;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.55rem;
  height: 2px;
  top: 0.85em;
  border-radius: 1px;
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
  font-style: italic;
  color: var(--ink);
}

.diary-page .diary-prose code,
.diary-page .diary-prose pre {
  font-family: var(--ff-plex-mono), ui-monospace, monospace;
}

.diary-page .diary-section:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-size: 4em;
  font-weight: 650;
  line-height: 0.82;
  color: var(--accent);
  margin: 0.05em 0.1em 0 0;
}

.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}
